public class ConsistentHash<T> {
    private final NavigableMap<Long, T> ring = new TreeMap<>();
    private final int vnodesPerNode;
    private final HashFunction hash;

    public void addNode(T node) {
        for (int i = 0; i < vnodesPerNode; i++) {
            long h = hash.hash((node.toString() + "#" + i).getBytes());
            ring.put(h, node);
        }
    }

    public T getNode(String key) {
        if (ring.isEmpty()) return null;
        long h = hash.hash(key.getBytes());
        Map.Entry<Long, T> e = ring.ceilingEntry(h);
        if (e == null) e = ring.firstEntry();           // wrap around
        return e.getValue();
    }

    public List<T> getReplicas(String key, int n) {
        Set<T> seen = new LinkedHashSet<>();
        long h = hash.hash(key.getBytes());
        Iterator<Map.Entry<Long, T>> it =
            ring.tailMap(h, true).entrySet().iterator();
        while (seen.size() < n) {
            if (!it.hasNext()) it = ring.entrySet().iterator();   // wrap
            seen.add(it.next().getValue());
        }
        return new ArrayList<>(seen);
    }

    public void removeNode(T node) {
        for (int i = 0; i < vnodesPerNode; i++) {
            long h = hash.hash((node.toString() + "#" + i).getBytes());
            ring.remove(h);
        }
    }
}
```

Notes:
- `TreeMap.ceilingEntry` is O(log N).
- For N replicas, walk clockwise skipping duplicate physical nodes.
- Use a strong hash (Murmur3, xxHash) — cryptographic hashes are unnecessary and slower.
